/**
 * Closes a milestone and moves its open live issues in one transaction: to
 * `moveTo` when given, otherwise out of any milestone. Closed and archived
 * issues are left where they are.
 */
export async function closeMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
): Promise<{
  readonly milestone: Milestone;
  readonly movedIssueIds: readonly IssueId[];
}> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const moved = tx
      .update(issues)
      .set({ milestoneId: moveTo, updatedAt: stamp })
      .where(openLiveIssuesIn(orgId, milestoneId))
      .returning({ id: issues.id })
      .all();

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${milestoneId} not found`);
    return {
      milestone: toMilestone(row),
      movedIssueIds: moved.map((issue) => issue.id as IssueId),
    };
  });
}

/**
 * Issue counts for every milestone of a project over live issues, in one
 * grouped read. Milestones with no live issues are absent from the map.
 */
export async function progressByMilestone(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ReadonlyMap<string, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNotNull(issues.milestoneId),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const progress = new Map<string, { total: number; open: number; closed: number }>();

  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const entry = progress.get(row.milestoneId) ?? { total: 0, open: 0, closed: 0 };
    const isClosed = (CLOSED_ISSUE_STATUSES as readonly string[]).includes(row.status);
    entry.total += row.value;
    if (isClosed) entry.closed += row.value;
    else entry.open += row.value;
    progress.set(row.milestoneId, entry);
  }

  return progress;
}
