/**
 * Milestone lifecycle: create, rename, re-date, close and reopen, plus the read side with progress and overdue flags.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, emit, milestoneNameKey, requireFound
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneProgress, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

/** The name as stored: surrounding spaces dropped, never empty. */
function cleanName(raw: string): string {
  const name = raw.trim();
  if (name.length === 0) throw new Error("Milestone name must not be blank");
  return name;
}

/** Names are unique per project, closed milestones included, ignoring `exceptId`. */
async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  nameKey: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const holder = await milestoneRepo.findMilestoneByNameKey(orgId, projectId, nameKey);
  if (holder !== null && holder.id !== exceptId) {
    throw new MilestoneStateError("name_taken");
  }
}

async function assertRoomForOpen(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

/** A milestone and its project, both looked up inside the actor's workspace. */
async function findWithProject(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ readonly milestone: Milestone; readonly project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  return { milestone, project };
}

/** The write gate for milestones: `project:update`, on a project that is not archived. */
function assertCanEdit(actor: Actor, project: Project): void {
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCanEdit(actor, project);

  const name = cleanName(input.name);
  await assertNameFree(input.orgId, project.id, milestoneNameKey(name), null);
  await assertRoomForOpen(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name,
    nameKey: milestoneNameKey(name),
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames, re-dates or clears the target date. Closed milestones may be edited too. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const { milestone, project } = await findWithProject(input.orgId, input.milestoneId);
  assertCanEdit(actor, project);

