  const progress = await milestoneRepo.progressByMilestone(orgId, project.id);
  const milestones = await milestoneRepo.listMilestones(orgId, project.id);

  return milestones
    .map((milestone) => withProgress(milestone, progress.get(milestone.id), now))
    .sort(compareForListing);
