/** Overdue: open, dated strictly in the past, and still holding open issues. */
function withProgress(
  milestone: Milestone,
  counts: MilestoneProgress | undefined,
  now: number,
): MilestoneWithProgress {
  const progress = counts ?? { total: 0, open: 0, closed: 0 };
  const overdue =
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    Date.parse(milestone.targetDate) < now &&
    progress.open > 0;
  return { milestone, progress, overdue };
}

function compareForListing(a: MilestoneWithProgress, b: MilestoneWithProgress): number {
  const aClosed = a.milestone.closedAt !== null ? 1 : 0;
  const bClosed = b.milestone.closedAt !== null ? 1 : 0;
  if (aClosed !== bClosed) return aClosed - bClosed;

  const aDate = a.milestone.targetDate === null ? Infinity : Date.parse(a.milestone.targetDate);
  const bDate = b.milestone.targetDate === null ? Infinity : Date.parse(b.milestone.targetDate);
  if (aDate !== bDate) return aDate < bDate ? -1 : 1;

  const created = Date.parse(a.milestone.createdAt) - Date.parse(b.milestone.createdAt);
  if (created !== 0) return created;
  return a.milestone.id < b.milestone.id ? -1 : a.milestone.id > b.milestone.id ? 1 : 0;
}
