/**
 * Milestone rules end to end: naming, the open cap, moving issues in and out,
 * closing (with the move and the alert it causes) and the progress read.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { NotFoundError } from "@/server/services/_support";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

function capture<K extends "milestone.closed" | "milestone.created">(
  type: K,
): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

function milestoneInput(name: string, targetDate: string | null = null) {
  return { orgId: tenant.org.id, projectId: tenant.project.id, name, targetDate };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones");
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

describe("createMilestone", () => {
  it("refuses a name already used in the project, ignoring case and surrounding spaces", async () => {
    const created = capture("milestone.created");
    await milestoneService.createMilestone(tenant.actors.admin, milestoneInput("Alpha"));

    await expect(
      milestoneService.createMilestone(tenant.actors.admin, milestoneInput("  alpha ")),
    ).rejects.toMatchObject({ reason: "name_taken" });
    expect(created).toHaveLength(1);
  });

  it("keeps a closed milestone's name reserved", async () => {
    const closing = await milestoneService.createMilestone(
      tenant.actors.admin,
      milestoneInput("Retired"),
    );
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: closing.id,
      moveOpenIssuesTo: null,
    });

    await expect(
      milestoneService.createMilestone(tenant.actors.admin, milestoneInput("RETIRED")),
    ).rejects.toBeInstanceOf(MilestoneStateError);
  });

  it("refuses an eleventh open milestone, and admits one again once another closes", async () => {
    const opened: string[] = [];
    while (opened.length < MAX_OPEN_MILESTONES_PER_PROJECT) {
      const milestone = await milestoneService.createMilestone(
        tenant.actors.admin,
        milestoneInput(`Sprint ${opened.length + 1}`),
      );
      opened.push(milestone.id);
    }

    await expect(
      milestoneService.createMilestone(tenant.actors.admin, milestoneInput("Overflow")),
    ).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: opened[0] as never,
      moveOpenIssuesTo: null,
    });
    await expect(
      milestoneService.createMilestone(tenant.actors.admin, milestoneInput("Overflow")),
    ).resolves.toMatchObject({ name: "Overflow" });
  });

  it("is refused for a viewer and for another workspace", async () => {
    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, milestoneInput("Nope")),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      milestoneService.createMilestone(tenant.actors.admin, {
        ...milestoneInput("Foreign"),
        orgId: "01HZZZBBBBBBBBBBBBBBBBBBBB" as never,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("closeMilestone", () => {
  it("moves open issues to the target, leaves closed ones behind, and alerts each assignee once", async () => {
    const source = await milestoneService.createMilestone(
      tenant.actors.admin,
      milestoneInput("Source"),
    );
    const target = await milestoneService.createMilestone(
      tenant.actors.admin,
      milestoneInput("Target"),
    );

    const open = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title: "Still open",
        assigneeId: tenant.userIds.member,
      }),
      milestoneId: source.id,
    } as never);
    const finished = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Already done" }),
      milestoneId: source.id,
    } as never);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: finished.id,
      status: "done",
    });

    const closed = capture("milestone.closed");
    const result = await milestoneService.closeMilestone(tenant.actors.owner, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: target.id,
    });

    expect(result.movedIssueIds).toEqual([open.id]);
    expect(closed).toHaveLength(1);
    expect(closed[0]).toMatchObject({
      movedToMilestoneId: target.id,
      movedIssueIds: [open.id],
    });

    const moved = await issueService.getIssue(tenant.actors.member, tenant.org.id, open.id);
    expect(moved.issue.milestoneId).toBe(target.id);
    const left = await issueService.getIssue(tenant.actors.member, tenant.org.id, finished.id);
    expect(left.issue.milestoneId).toBe(source.id);

    const alerts = await notificationService.listNotifications(tenant.actors.member, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 100,
      cursor: null,
    });
    const milestoneAlerts = alerts.items.filter(
      (item) => item.kind === "issue_milestone_changed",
    );
    expect(milestoneAlerts).toHaveLength(1);
  });

  it("refuses a target that is closed, is the milestone itself, or sits in another project", async () => {
    const source = await milestoneService.createMilestone(
      tenant.actors.admin,
      milestoneInput("Guarded"),
    );
    const retired = await milestoneService.createMilestone(
      tenant.actors.admin,
      milestoneInput("Guarded target"),
    );
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: retired.id,
      moveOpenIssuesTo: null,
    });

    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: retired.id,
      }),
    ).rejects.toMatchObject({ reason: "closed" });

    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: source.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const other = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhere = await milestoneService.createMilestone(tenant.actors.admin, {
      ...milestoneInput("Elsewhere goal"),
      projectId: other.id,
    });
    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: elsewhere.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stillOpen = await milestoneService.getMilestone(
      tenant.actors.admin,
      tenant.org.id,
      source.id,
    );
    expect(stillOpen.milestone.closedAt).toBeNull();
  });

  it("refuses closing a milestone that is already closed", async () => {
    const once = await milestoneService.createMilestone(
      tenant.actors.admin,
      milestoneInput("Once"),
    );
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: once.id,
      moveOpenIssuesTo: null,
    });

    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: once.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toMatchObject({ reason: "closed" });
  });
});

describe("listMilestones", () => {
  it("lists open milestones first, dated before undated, and reports overdue open work", async () => {
    const late = await milestoneService.createMilestone(
      tenant.actors.admin,
      milestoneInput("Past due", "2020-01-01T00:00:00.000Z"),
    );
    await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Late work" }),
      milestoneId: late.id,
    } as never);

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      tenant.project.id,
    );

    const openFirst = listed.findIndex((entry) => entry.milestone.closedAt !== null);
    const closedAfterOpen = listed.slice(0, openFirst).every((entry) => entry.milestone.closedAt === null);
    expect(closedAfterOpen).toBe(true);

    const pastDue = listed.find((entry) => entry.milestone.id === late.id);
    expect(pastDue?.overdue).toBe(true);
    expect(pastDue?.progress).toEqual({ total: 1, open: 1, closed: 0 });
  });
});
EOF
